## solutions

#### depth first

```cpp
#include <vector>
#include <unordered_map>

int traverse(std::unordered_map<char, std::vector<char>> graph, std::unordered_map<char, int> &distance, char node) {
  if (distance.count(node) > 0) {
    return distance[node];
  }

  int max = 0;
  for (char neighbor : graph[node]) {
    int neighborDistance = traverse(graph, distance, neighbor);
    if (neighborDistance > max) {
      max = neighborDistance;
    }
  }

  distance[node] = 1 + max;
  return distance[node];
}

int longestPath(std::unordered_map<char, std::vector<char>> graph) {
  std::unordered_map<char, int> distance;
  for (auto pair : graph) {
    char node = pair.first;
    std::vector<char> neighbors = pair.second;
    if (neighbors.size() == 0) {
      distance[node] = 0;
    }
  }

  for (auto pair : graph) {
    char node = pair.first;
    traverse(graph, distance, node);
  }

  int longest = 0;
  for (auto pair : distance) {
    if (pair.second > longest) {
      longest = pair.second;
    }
  }
  return longest;
}
```

- e = # edges
- n = # nodes
- Time: O(e)
- Space: O(n)
